#![cfg(feature="player")]
#[path="support/audio_transitions.rs"]mod transitions;
#[path="support/rational_audio_seek.rs"]mod rational;
use fvid::audio::AudioStream;
use std::{io::Cursor,time::Duration,sync::{Arc,Mutex}};
use rational::{Packet,collect,exact};
fn root()->std::path::PathBuf{std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/playback-errors/audio-index-eof")}
fn bytes(n:&str)->Vec<u8>{std::fs::read(root().join(n)).unwrap()}
fn cases()->Vec<serde_json::Value>{serde_json::from_slice::<serde_json::Value>(&bytes("manifest.json")).unwrap()["cases"].as_array().unwrap().clone()}
fn stream(c:&serde_json::Value)->Box<dyn AudioStream>{let b=bytes(c["file"].as_str().unwrap());match c["kind"].as_str().unwrap(){"wav"=>Box::new(fvid::playback_wav::WavAudioReader::open(b.as_slice(),Default::default()).unwrap()),"aiff"=>Box::new(fvid::playback_aiff::AiffAudioReader::open(b.as_slice(),Default::default()).unwrap()),"au"=>Box::new(fvid::playback_au::AuAudioReader::open(b.as_slice(),Default::default()).unwrap()),_=>unreachable!()}}
fn expected(c:&serde_json::Value,first:usize)->Vec<Packet>{let frames=c["frames"].as_u64().unwrap()as usize;if first==frames{return vec![];}let ch=c["channels"].as_u64().unwrap()as u16;vec![Packet{rate:8000,channels:ch,num:first as u128,den:8000,data:bytes(c["oracle"].as_str().unwrap())[first*usize::from(ch)*4..].to_vec()}]}
enum Index{Wav(fvid::playback_wav::Wav),Aiff(fvid::playback_aiff::Aiff),Au(fvid::playback_au::Au)}
impl Index{fn open(c:&serde_json::Value)->Self{let b=bytes(c["file"].as_str().unwrap());match c["kind"].as_str().unwrap(){"wav"=>Self::Wav(fvid::playback_wav::Wav::parse(&b,&Default::default()).unwrap()),"aiff"=>Self::Aiff(fvid::playback_aiff::Aiff::parse(&b,&Default::default()).unwrap()),"au"=>Self::Au(fvid::playback_au::Au::parse(&b,&Default::default()).unwrap()),_=>unreachable!()}}fn len(&self)->usize{match self{Self::Wav(x)=>x.packets(),Self::Aiff(x)=>x.packets(),Self::Au(x)=>x.packets()}}fn packet(&self,n:usize)->&[u8]{match self{Self::Wav(x)=>x.packet(n),Self::Aiff(x)=>x.packet(n),Self::Au(x)=>x.packet(n)}}}
#[test]fn valid_indexed_packets_and_normal_playback_match_independent_pcm(){for c in cases(){let index=Index::open(&c);let mut source=stream(&c);let mut encoded=Vec::new();while let Some(p)=source.next_packet().unwrap(){encoded.extend(p.data);}assert_eq!((0..index.len()).flat_map(|n|index.packet(n).iter().copied()).collect::<Vec<_>>(),encoded);source.rewind();exact(&collect(&mut *source),&expected(&c,0),c["file"].as_str().unwrap());}let mut v=fvid::playback_native::NativeReader::software(Cursor::new(bytes("neutral-video.mp4")),32<<20).unwrap();for _ in 0..6{assert_eq!(v.read_frame_raw().unwrap().unwrap().into_rgb(32<<20).unwrap(),vec![130;16*16*3]);}assert!(v.read_frame_raw().unwrap().is_none());}
fn check_index_eof(kind:&str){for c in cases().into_iter().filter(|c|c["kind"].as_str()==Some(kind)){let index=Index::open(&c);let first=index.packet(0).to_vec();let last=index.packet(index.len()-1).to_vec();assert!(!last.is_empty());for n in [index.len(),index.len()+1,usize::MAX]{assert!(index.packet(n).is_empty(),"{}:index{n} repeated {} tail bytes",c["file"].as_str().unwrap(),index.packet(n).len());}let mut actual=Vec::new();let mut ended=false;for n in 0..index.len()+4{let data=index.packet(n);if data.is_empty(){ended=true;break;}actual.extend_from_slice(data);}assert!(ended,"bounded indexed consumer never reaches EOF");assert_eq!(actual.len(),c["frames"].as_u64().unwrap()as usize*c["channels"].as_u64().unwrap()as usize*2);assert_eq!(index.packet(0),first);assert_eq!(index.packet(index.len()-1),last);}}
#[test]fn actual_reader_worker_keeps_seek_and_end_of_stream(){use fvid::audio_thread::AudioPlayback;use transitions::{Capture,Trace,ended};for c in cases(){let frames=c["frames"].as_u64().unwrap()as usize;let first=frames-1;let raw=Arc::new(Mutex::new(rational::RawTrace::default()));let captured=raw.clone();let trace=Arc::new(Mutex::new(Trace::default()));let mut worker=AudioPlayback::start(stream(&c),move||Box::new(rational::RawCapture{inner:Capture::new(trace),raw:captured}));worker.seek(Duration::from_micros(first as u64*125));worker.play();ended(&worker,worker.generation());let got=raw.lock().unwrap();exact(&got.packets,&expected(&c,first),c["file"].as_str().unwrap());assert_eq!(got.anchors,vec![Duration::from_micros(first as u64*125)]);}}

#[test]fn wave_index_reaches_eof(){check_index_eof("wav");}
#[test]fn aiff_index_reaches_eof(){check_index_eof("aiff");}
#[test]fn au_index_reaches_eof(){check_index_eof("au");}
